#include <stdio.h>
#include <stdlib.h>
#include <string.h>
int main(void){int n,i;static long long a[500005];if(scanf("%d",&n)!=1)return 1;for(i=0;i<n;i++)scanf("%lld",&a[i]);long long k;if(scanf("%lld",&k)!=1)return 1;long long best=1000000000LL,s=0;int l=0,r2;for(r2=0;r2<n;r2++){s+=a[r2];while(s>=k){long long len=r2-l+1;if(len<best)best=len;s-=a[l];l++;}}printf("%lld\n",best==1000000000LL?-1:best);return 0;}
